  </div>

  <!-- SECTOR CONCENTRATION -->
  <div class="section">
    <div class="section-title">Sector Concentration</div>
    <div class="section-subtitle">Technology and semiconductor companies dominate the highest market cap positions, with only a few non-tech exceptions.</div>
    <div class="infographic-container list-grid" id="container-sectors"></div>
  </div>

  <!-- PERSPECTIVE -->
  <div class="section">
    <div class="section-title">Putting It in Perspective</div>
    <div class="section-subtitle">The concentration at the top is extreme. NVIDIA alone exceeds the combined value of the bottom 5,000+ tracked companies.</div>
    <div class="infographic-container compare-section" id="container-compare"></div>
  </div>

  <!-- FOOTER / KEY STATS -->
  <div class="footer">
    <div class="footer-stat-row">
      <div class="footer-stat">
        <div class="footer-stat-value"><span class="accent-blue">$25.4</span>T</div>
        <div class="footer-stat-label">Top 10 Combined Market Cap</div>
      </div>
      <div class="footer-stat">
        <div class="footer-stat-value"><span class="accent">$142.9</span>T</div>
        <div class="footer-stat-label">Total Global Market Cap</div>
      </div>
      <div class="footer-stat">
        <div class="footer-stat-value">10,796</div>
        <div class="footer-stat-label">Companies Tracked</div>
      </div>
      <div class="footer-stat">
        <div class="footer-stat-value">11</div>
        <div class="footer-stat-label">Trillion-Dollar Companies</div>
      </div>
    </div>
    <div class="source-note">Data: Global public equity markets, mid-2025. Top 10 companies (~0.09% of firms) hold ~18% of total global market value.</div>
  </div>

</div>

<script src="/app/vendor/infographic.min.js"></script>
<script>
const infographics = [];

function renderAll() {
  // 1. Trillion-Dollar Club - Bar Chart
  const ig1 = new AntVInfographic.Infographic({
    container: '#container-bar',
    width: 704,
    height: 600,
  });
  ig1.render(`infographic chart-bar-plain-text
data
  title
  values
    - label NVIDIA
      value 4.82
    - label Alphabet
      value 4.03
    - label Apple
      value 3.87
    - label Microsoft
      value 3.12
    - label Amazon
      value 2.69
    - label Broadcom
      value 1.89
    - label TSMC
      value 1.88
    - label Aramco
      value 1.77
    - label Meta
      value 1.71
    - label Tesla
      value 1.46
    - label Berkshire
      value 1.02
theme
  palette #4fc3f7 #4fc3f7 #4fc3f7 #4fc3f7 #4fc3f7 #4fc3f7 #4fc3f7 #ffd54f #4fc3f7 #4fc3f7 #4fc3f7
  stylize linear-gradient`);
  infographics.push(ig1);

  // 2. Country Dominance - Donut
  const ig2 = new AntVInfographic.Infographic({
    container: '#container-pie',
    width: 704,
    height: 340,
  });
  ig2.render(`infographic chart-pie-donut-plain-text
data
  title
  values
    - label United States
      value 15
    - label Taiwan
      value 1
    - label Saudi Arabia
      value 1
    - label South Korea
      value 1
    - label China
      value 1
    - label Netherlands
      value 1
theme
  palette #4fc3f7 #ffd54f #e57373 #81c784 #64b5f6 #ce93d8`);
  infographics.push(ig2);

  // 3. Sector Concentration
  const ig3 = new AntVInfographic.Infographic({
    container: '#container-sectors',
    width: 704,
    height: 320,
  });
  ig3.render(`infographic list-grid-badge-card
data
  title
  lists
    - label Semiconductors
      desc NVIDIA, Broadcom, TSMC
      icon cpu chip
    - label Software & Cloud
      desc Microsoft, Alphabet, Amazon
      icon cloud server
    - label Consumer Tech
      desc Apple, Meta
      icon device phone
    - label Automotive
      desc Tesla
      icon car
    - label Energy
      desc Saudi Aramco
      icon fuel
    - label Diversified
      desc Berkshire Hathaway
      icon building office
theme
  palette #4fc3f7 #4fc3f7 #4fc3f7 #ffd54f #e57373 #81c784`);
  infographics.push(ig3);

  // 4. Scale Context - Column comparison
  const ig4 = new AntVInfographic.Infographic({
    container: '#container-compare',
    width: 704,
    height: 420,
  });
  ig4.render(`infographic chart-column-simple
data
  title
  desc Rank 1 to Rank 20 represents a nearly 9x drop in valuation
  values
    - label NVIDIA\n#1
      value 4.82
    - label Top 5\nCombined
      value 3.70
    - label Top 10\nAvg
      value 2.54
    - label Top 20\nAvg
      value 0.97
    - label Rank 20\nASML
      value 0.554
    - label Bottom\n5000+
      value 0.0086
theme
  palette #4fc3f7 #4fc3f7 #4fc3f7 #ffd54f #8892b0 #1a2540
  stylize linear-gradient`);
  infographics.push(ig4);
}

renderAll();

document.fonts?.ready?.then(() => {
  infographics.forEach(ig => {
    try { ig.render(ig.getOptions().syntax); } catch(e) {}
  });
}).catch(() => {});
</script>
</body>
</html>
