node -e "
const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 800, height: 3000, deviceScaleFactor: 1 });

  const htmlPath = 'file://' + path.resolve('/app/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle0', timeout: 30000 });
  await new Promise(r => setTimeout(r, 3000));

  // Check text elements in each SVG
  const textInfo = await page.evaluate(() => {
    const containers = document.querySelectorAll('.infographic-container');
    return Array.from(containers).map(c => {
      const svg = c.querySelector('svg');
      if (!svg) return { id: c.id, error: 'no svg' };
      const texts = svg.querySelectorAll('text');
      const samples = Array.from(texts).slice(0, 10).map(t => ({
        content: t.textContent.trim(),
        x: t.getAttribute('x'),
        y: t.getAttribute('y'),
        fill: t.getAttribute('fill') || 'none',
        fontSize: t.getAttribute('font-size') || 'none'
      }));
      return {
        id: c.id,
        totalTextElements: texts.length,
        samples: samples
      };
    });
  });
  console.log(JSON.stringify(textInfo, null, 2));
  await browser.close();
})();
