const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();

  await page.setViewport({ width: 800, height: 3000, deviceScaleFactor: 2 });

  const htmlPath = 'file://' + path.resolve('/app/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for all SVG elements to be fully rendered
  await page.waitForFunction(() => {
    const containers = document.querySelectorAll('.infographic-container');
    if (containers.length < 4) return false;
    for (const c of containers) {
      const svg = c.querySelector('svg');
      if (!svg) return false;
      if (svg.querySelectorAll('*').length < 50) return false;
    }
    return true;
  }, { timeout: 20000 });

  // Allow final render pass after fonts
  await page.evaluate(() => new Promise(r => setTimeout(r, 2000)));

  // Get exact poster dimensions
  const dimensions = await page.evaluate(() => {
    const poster = document.getElementById('poster');
    const rect = poster.getBoundingClientRect();
    return { x: rect.x, y: rect.y, width: rect.width, height: rect.height };
  });

  console.log('Poster dimensions:', dimensions.width, 'x', dimensions.height);

  // Full page screenshot clipped to poster
  await page.screenshot({
    path: '/app/output/final_poster.png',
    clip: {
      x: dimensions.x,
      y: dimensions.y,
      width: dimensions.width,
      height: dimensions.height
    },
    omitBackground: true
  });

  console.log('Poster saved to /app/output/final_poster.png');
  console.log('Final size:', Math.round(dimensions.width * 2), 'x', Math.round(dimensions.height * 2));

  await browser.close();
})();

